const upsertConversation = `-- name: UpsertConversation :one
insert into conversations (id, org_id, session_id, opencode_id, title, created_at, updated_at, info, parent_opencode_id)
values ($1, $2, $3, $4, $5, $6, $7, $8, $9)
on conflict (session_id, opencode_id) do update
set title              = case when excluded.title = '' then conversations.title else excluded.title end,
    info               = coalesce(excluded.info, conversations.info),
    parent_opencode_id = coalesce(excluded.parent_opencode_id, conversations.parent_opencode_id),
    updated_at         = excluded.updated_at
returning id, org_id, session_id, opencode_id, title, created_at, updated_at, info, seq_base, seq_after, parent_opencode_id
`

type UpsertConversationParams struct {
	ID               string
	OrgID            string
	SessionID        string
	OpencodeID       string
	Title            string
	CreatedAt        pgtype.Timestamptz
	UpdatedAt        pgtype.Timestamptz
	Info             []byte
	ParentOpencodeID *string
}

// An existing row keeps its id and created_at; the title, the info and
// the parent change only when the new one says something.
func (q *Queries) UpsertConversation(ctx context.Context, arg UpsertConversationParams) (Conversation, error) {
	row := q.db.QueryRow(ctx, upsertConversation,
		arg.ID,
		arg.OrgID,
		arg.SessionID,
		arg.OpencodeID,
		arg.Title,
		arg.CreatedAt,
		arg.UpdatedAt,
		arg.Info,
		arg.ParentOpencodeID,
	)
	var i Conversation
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.SessionID,
		&i.OpencodeID,
		&i.Title,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Info,
		&i.SeqBase,
		&i.SeqAfter,
		&i.ParentOpencodeID,
	)
	return i, err
}

const useImage = `-- name: UseImage :exec
insert into images (name, image_id, kind, request_key, versions, published_at, last_used_at)
values ($1, $2, $3, $4, $5, $6, $6)
on conflict (name) do update
set last_used_at = greatest(images.last_used_at, excluded.last_used_at)
where images.deleted_at is null
`

type UseImageParams struct {
	Name        string
	ImageID     string
	Kind        string
	RequestKey  string
	Versions    []byte
	PublishedAt pgtype.Timestamptz
}

// Enters an unknown name as published at its first use; moves a known,
// undeleted one's last use forward.
//
// @decision(DL-016)
func (q *Queries) UseImage(ctx context.Context, arg UseImageParams) error {
	_, err := q.db.Exec(ctx, useImage,
		arg.Name,
		arg.ImageID,
		arg.Kind,
		arg.RequestKey,
		arg.Versions,
		arg.PublishedAt,
	)
	return err
}
